import React from 'react';

const Icon = ({ size = 16, color = 'currentColor', title, children, ...props }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none"
    stroke={color} 
    strokeWidth="1.5" 
    strokeLinecap="round" 
    strokeLinejoin="round"
    aria-hidden={!title} 
    role={title ? 'img' : undefined} 
    {...props}
  >
    {title && <title>{title}</title>}
    {children}
  </svg>
);

